package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;

/** Within-group case bootstrap, group-specific intervals and all-pairs bias-centred PLS-MGA. */
public final class PlsGroupBootstrap {
    private PlsGroupBootstrap(){}
    public record Comparison(Bootstrap.Parameter parameter,Bootstrap.Estimate groupA,Bootstrap.Estimate groupB,double difference,GroupInference.Test parametric,GroupInference.Test welch,double mgaDirectionalP,double mgaTestP,boolean correctedIntervalsOverlap,boolean correctedIntervalsAvailable,EmpiricalHistogram groupAHistogram,EmpiricalHistogram groupBHistogram,double[] groupADraws,double[] groupBDraws){public Comparison{groupADraws=copy(groupADraws);groupBDraws=copy(groupBDraws);}@Override public double[] groupADraws(){return copy(groupADraws);}@Override public double[] groupBDraws(){return copy(groupBDraws);}private static double[] copy(double[] a){return a==null?null:a.clone();}}
    public record Result(PlsGroups.Point point,Bootstrap.Options options,boolean retainedDraws,int successful,int failed,Map<String,Integer> failures,List<Comparison> comparisons,List<String> warnings,String sampling,String method){public Result{failures=Collections.unmodifiableMap(new LinkedHashMap<>(failures));comparisons=List.copyOf(comparisons);warnings=List.copyOf(warnings);}}
    public static Result fit(double[][] observations,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options modelOptions,PlsGroups.Selection selection,boolean consistent,Bootstrap.Options options,boolean retainDraws,IntConsumer progress){
        var context=new PlsGroups.Context(observations,blocks,edges,modelOptions,selection,consistent);var point=context.point;int terms=point.parameters().size();if(terms==0)throw new IllegalArgumentException("No finite, comparable group targets.");if((long)terms*options.samples()*2>20000000L||retainDraws&&(long)terms*options.samples()*2>1000000L)throw new IllegalArgumentException("Group bootstrap storage is too large; reduce model/sample count or disable retained draws.");boolean reference=options.convention()==RegressionBootstrap.Convention.REFERENCE_4_1_2_1;double[] originalA=context.values(point.groupA()),originalB=context.values(point.groupB());List<double[]> acceptedA=new ArrayList<>(),acceptedB=new ArrayList<>();Map<String,Integer> failures=new LinkedHashMap<>();Random random=new Random(options.seed());long[] seeds=reference?ReferenceResampling.seeds(options.seed(),options.samples()):null;
        for(int attempt=0;attempt<options.samples();attempt++){
            Matrices.interrupted();int[] a=draw(reference?new Random(seeds[attempt]):random,context.a,reference),b=draw(reference?new Random(seeds[attempt]):random,context.b,reference);
            try{double[] va=context.values(context.group(selection.nameA(),a,a)),vb=context.values(context.group(selection.nameB(),b,b));acceptedA.add(va);acceptedB.add(vb);}catch(IllegalArgumentException|ArithmeticException problem){failures.merge(problem.getMessage()==null?problem.getClass().getSimpleName():problem.getMessage(),1,Integer::sum);}if(progress!=null)progress.accept(attempt+1);
        }
        int count=acceptedA.size(),failed=options.samples()-count;if(count<Math.max(30,(int)Math.ceil(options.samples()*.8)))throw new IllegalArgumentException("Too few usable group bootstrap pairs: "+count+"/"+options.samples()+"; "+failures);List<String> warnings=new ArrayList<>();double[][] jackA=null,jackB=null;if(!reference&&options.interval()==BootstrapIntervals.Method.BCA){if((long)(context.a.length+context.b.length)*terms>20000000L)throw new IllegalArgumentException("Group jackknife storage is too large.");jackA=jackknife(context,context.a,selection.nameA(),terms,warnings);jackB=jackknife(context,context.b,selection.nameB(),terms,warnings);}
        List<Comparison> comparisons=new ArrayList<>();for(int j=0;j<terms;j++){
            Matrices.interrupted();double[] a=PlsPermutation.column(acceptedA,j),b=PlsPermutation.column(acceptedB,j);var ea=estimate(point.parameters().get(j),originalA[j],a,options,jackA==null?null:column(jackA,j));var eb=estimate(point.parameters().get(j),originalB[j],b,options,jackB==null?null:column(jackB,j));var tests=GroupInference.evaluate(originalA[j],originalB[j],ea.standardError(),eb.standardError(),context.a.length,context.b.length,reference,options.twoSided());double directional=GroupInference.nonparametric(originalA[j],originalB[j],a,b,reference),mga=Double.isNaN(directional)?Double.NaN:2*Math.min(directional,1-directional)/(options.twoSided()?1:2);boolean overlap=ea.correctedInterval().lower()<=eb.correctedInterval().upper()&&eb.correctedInterval().lower()<=ea.correctedInterval().upper();comparisons.add(new Comparison(point.parameters().get(j),ea,eb,originalA[j]-originalB[j],tests.parametric(),tests.welch(),directional,mga,overlap,!Double.isNaN(ea.correctedInterval().lower())&&!Double.isNaN(ea.correctedInterval().upper())&&!Double.isNaN(eb.correctedInterval().lower())&&!Double.isNaN(eb.correctedInterval().upper()),EmpiricalHistogram.of(a),EmpiricalHistogram.of(b),retainDraws?a:null,retainDraws?b:null));
        }
        if(failed>0)warnings.add(failed+" bootstrap pairs failed and were excluded without replacement; both group fits must succeed. Inference is conditional on usable pairs.");if(options.samples()<1000)warnings.add("Fewer than 1000 bootstrap attempts; use a larger run for substantive inference.");warnings.add("Establish measurement invariance before interpreting group parameter differences. Non-overlap of separate confidence intervals is conservative and is not a confidence interval for the difference.");if(reference)warnings.add("Reference formulas retain population bootstrap SD, shared per-group resampling seeds, rounded unequal-variance degrees of freedom, strict all-pairs comparisons and the original zero-standard-error behavior. Standard mode uses sample SD, independent sequential draws, half-weighted ties and standard coefficient-variance approximations.");if(!point.unavailableTargets().isEmpty())warnings.add("Unavailable group targets were omitted: "+String.join("; ",point.unavailableTargets()));if(comparisons.stream().anyMatch(c->c.groupA().standardError()==0||c.groupB().standardError()==0))warnings.add("Some group bootstrap distributions have zero variance; inspect undefined uncertainty and the selected convention before interpreting p-values.");
        if(reference&&comparisons.stream().anyMatch(c->c.difference()==0&&c.mgaTestP()==0))warnings.add("Reference strict all-pairs ties can yield a zero MGA test probability for identical group estimates; do not interpret these as significant differences. Use standard mode.");
        return new Result(point,options,retainDraws,count,failed,failures,comparisons,warnings,reference?"Reference two-stage seeds and bounded-integer/modulus rows; same sample seed for each group":"java.util.Random nextInt(group size); independent sequential within-group draws; version 1","Group-specific case-bootstrap intervals; pooled and unequal-variance MGA approximations; bias-centred all-pairs nonparametric PLS-MGA with O(B log B) counts and long integer totals. No paired-difference CI is inferred from reference shared-seed draws.");
    }
    private static int[] draw(Random random,int[] group,boolean reference){int[] rows=new int[group.length];for(int i=0;i<rows.length;i++)rows[i]=group[reference?random.nextInt(Integer.MAX_VALUE)%group.length:random.nextInt(group.length)];return rows;}
    private static double[][] jackknife(PlsGroups.Context context,int[] group,String name,int terms,List<String> warnings){double[][] result=new double[group.length][terms];int failed=0;for(int omit=0;omit<group.length;omit++){Matrices.interrupted();Arrays.fill(result[omit],Double.NaN);int[] rows=new int[group.length-1];for(int i=0,k=0;i<group.length;i++)if(i!=omit)rows[k++]=group[i];try{result[omit]=context.values(context.group(name,rows,rows));}catch(IllegalArgumentException|ArithmeticException problem){failed++;}}if(failed>0)warnings.add(name+": "+failed+" jackknife fits failed; affected standard BCa intervals are unavailable.");return result;}
    private static double[] column(double[][] values,int j){double[] result=new double[values.length];for(int i=0;i<values.length;i++)result[i]=values[i][j];return result;}
    private static Bootstrap.Estimate estimate(Bootstrap.Parameter term,double point,double[] values,Bootstrap.Options options,double[] jackknife){
        boolean reference=options.convention()==RegressionBootstrap.Convention.REFERENCE_4_1_2_1;double mean=0,sum=0;for(int i=0;i<values.length;i++){double delta=values[i]-mean;mean+=delta/(i+1);sum+=delta*(values[i]-mean);}double se=Math.sqrt(Math.max(0,sum/(values.length-1))),statistic=Math.abs(Inference.ratio(point,se)),p=Inference.normalTwoSided(statistic);BootstrapIntervals.Interval interval,corrected;
        if(reference){var inference=ReferenceBootstrapInference.evaluate(point,values,options.confidence(),options.interval(),options.twoSided());mean=inference.mean();se=inference.standardError();statistic=inference.statistic();p=inference.pValue();interval=inference.interval();corrected=inference.correctedInterval();}else{interval=BootstrapIntervals.calculate(point,values,options.confidence(),options.interval(),Double.NaN,null,jackknife);corrected=BootstrapIntervals.biasCorrected(point,values,options.confidence());}return new Bootstrap.Estimate(term,point,mean,se,statistic,p,interval.lower(),interval.upper(),interval,corrected);
    }
}
